import { Box, Container, Link, Stack, Typography } from "@mui/material";
import { mediaUrl } from "../services/api";
import type { HomeSubFooter } from "../types/home";
import appStoreBadge from "../assets/icons/appstore-apple.png";
import playStoreBadge from "../assets/icons/g-play.png";

const NAVY = "#17224d";
const APP_STORE_URL = "https://apps.apple.com/in/app/doctutorials-neet-pg-ss-fmge/id1475350376";
const PLAY_STORE_URL = "https://play.google.com/store/apps/details?id=in.dgist.doctutorials&hl=en_US";

export default function SubFooter({ data }: { data?: HomeSubFooter | null }) {
  if (!data) return null;

  const appStoreSrc = mediaUrl(data.appStoreImage) || appStoreBadge;
  const playStoreSrc = mediaUrl(data.playStoreImage) || playStoreBadge;

  return (
    <Box sx={{ py: { xs: 6, md: 8 }, backgroundColor: "#fff" }}>
      <Container maxWidth="lg">
        <Stack
          direction={{ xs: "column", md: "row" }}
          alignItems="center"
          spacing={{ xs: 5, md: 4 }}
          justifyContent="space-between"
        >
          <Box sx={{ flex: 1, width: "100%" }}>
            {data.coursesTitle ? (
              <Typography sx={{ color: NAVY, fontSize: 22, fontWeight: 700, mb: 1.5 }}>
                {data.coursesTitle}
              </Typography>
            ) : null}
            <Box component="ul" sx={{ m: 0, pl: 2.5, mb: 3 }}>
              {(data.courses || []).map((item) => (
                <Box component="li" key={item.id || item.label} sx={{ mb: 0.75 }}>
                  <Link
                    href={item.url}
                    target={item.openInNewTab ? "_blank" : undefined}
                    rel={item.openInNewTab ? "noopener noreferrer" : undefined}
                    underline="hover"
                    sx={{ color: NAVY, fontSize: 15 }}
                  >
                    {item.label}
                  </Link>
                </Box>
              ))}
            </Box>
            {data.centersTitle ? (
              <Typography sx={{ color: NAVY, fontSize: 22, fontWeight: 700, mb: 1.5 }}>
                {data.centersTitle}
              </Typography>
            ) : null}
            <Typography sx={{ color: NAVY, fontSize: 15 }}>
              {(data.centers || []).map((item, index) => (
                <Box component="span" key={item.id || item.label}>
                  {index > 0 ? " | " : null}
                  <Link
                    href={item.url}
                    target={item.openInNewTab ? "_blank" : undefined}
                    rel={item.openInNewTab ? "noopener noreferrer" : undefined}
                    underline="hover"
                    sx={{ color: NAVY }}
                  >
                    {item.label}
                  </Link>
                </Box>
              ))}
            </Typography>
          </Box>

          {mediaUrl(data.centerImage) ? (
            <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
              <Box
                component="img"
                src={mediaUrl(data.centerImage)}
                alt=""
                sx={{ width: "100%", maxWidth: 450, display: "block", mx: "auto" }}
              />
            </Box>
          ) : null}

          <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
            {data.qrTitle ? (
              <Typography sx={{ color: NAVY, fontSize: 22, fontWeight: 700, mb: 2 }}>
                {data.qrTitle}
              </Typography>
            ) : null}
            {mediaUrl(data.qrImage) ? (
              <Box
                component="img"
                src={mediaUrl(data.qrImage)}
                alt="QR"
                sx={{ width: 142, display: "block", mx: "auto", mb: 1.5 }}
              />
            ) : null}
            <Typography sx={{ color: NAVY, fontSize: 16, mb: 2 }}>{data.qrOrText || "OR"}</Typography>
            <Stack direction="row" justifyContent="center" spacing={1.5} flexWrap="wrap" useFlexGap>
              <Box
                component="a"
                href={data.appStoreUrl || APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box component="img" src={appStoreSrc} alt="App Store" sx={{ height: 40 }} />
              </Box>
              <Box
                component="a"
                href={data.playStoreUrl || PLAY_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box component="img" src={playStoreSrc} alt="Play Store" sx={{ height: 40 }} />
              </Box>
            </Stack>
          </Box>
        </Stack>
      </Container>
    </Box>
  );
}
